/**
 * A city/postal-code entry usable for address lookup, independent of country.
 * Static reference data generated by `tools/generate-city-data.mjs` into
 * `assets/cities/<CC>.json` — never stored in Firestore. CH and LI come from the official
 * swisstopo locality list (the register behind the swisstopo address search), all other
 * countries from GeoNames postal codes (CC BY 4.0).
 *
 * The optional fields are only set where the source carries them:
 * municipality for CH, LI and AT, district for AT, coordinates for (almost) every entry.
 */
export interface City {
  zipCode: string;
  name: string;           // locality as used in a postal address, e.g. "Olivone"
  stateCode: string;      // canton / state code (CH "TI", DE "BY", US "CA"); region name for AT/IT/FR
  countryCode: string;    // ISO 3166-1 alpha-2
  municipality?: string;  // political municipality the locality belongs to, e.g. "Blenio"
  municipalityCode?: string; // official number: BFS-Nr (CH, LI), Gemeindekennziffer (AT)
  district?: string;      // district above the municipality (AT politischer Bezirk)
  latitude?: number;      // WGS84
  longitude?: number;     // WGS84
}

/** Countries for which a city/zip dataset exists (all lazy-fetched from /assets/cities/<CC>.json). */
export const SUPPORTED_CITY_COUNTRIES = ['CH', 'LI', 'DE', 'AT', 'IT', 'FR', 'US', 'GB'] as const;
export type SupportedCityCountry = (typeof SUPPORTED_CITY_COUNTRIES)[number];
